'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const S=require('./cleanup-schema.cjs'),B=require('./cleanup-backend.cjs'),X=require('./fence-fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT;assert(root&&fs.existsSync(root));const dir=()=>fs.mkdtempSync(path.join(root,'native-name-pair-'));
const known='Recover owned KeyDB parity qualification / Close KeyDB qualification known identities ';
function other(f,executed=false){const active=f.jobMap.get(888),job={...active,id:889,name:known+S.slot(f.c.actor.target_locator),status:'completed',conclusion:executed?'failure':'skipped',runner_id:executed?999:0,runner_name:executed?active.runner_name:'',steps:executed?[{name:S.STEP,number:5,status:'completed',conclusion:'failure',started_at:'2026-10-24T15:01:01Z',completed_at:'2026-10-24T15:01:02Z'}]:[]};f.jobMap.set(889,job);return job;}
test('actual unused actor/reader/history accepts distinct nonselected skipped known native handler',async()=>{const f=X.fixture(dir());other(f);const b=await B.readTarget(f.c,f.deps);assert.equal(b.actor.job_id,888);const h=await B.handlerHistory(f.c,b,[],f.deps);assert.equal(h.handlers.length,2);assert(h.handlers.some(j=>j.job_id===889&&j.executed===false));assert(h.handlers.some(j=>j.job_id===888&&j.executed===true));assert.deepEqual(h.wire_clear,{remove:true});});
test('executed distinct known native handler with no recognized effect history still blocks unused cleanup',async()=>{const f=X.fixture(dir());other(f,true);const b=await B.readTarget(f.c,f.deps);await assert.rejects(B.handlerHistory(f.c,b,[],f.deps));});
test('duplicate exact unused native matches remain ambiguity HOLD',async()=>{const f=X.fixture(dir());const active=f.jobMap.get(888);f.jobMap.set(889,{...active,id:889,status:'completed',conclusion:'skipped',runner_id:0,runner_name:'',steps:[]});await assert.rejects(B.readTarget(f.c,f.deps));});
test('real immutable remove phase persistence retains skipped handler and bounded native reads',async()=>{const f=X.fixture(dir());other(f);const b=await B.readTarget(f.c,f.deps),held=[],counts=[];for(const phase of ['NO_WIRE','UNKNOWN','ACK']){const start=f.calls.length,r=X.removal(f.c,b,phase,held.length?S.hash(held.at(-1).record):null),a=await B.persist(r,f.c,b,held,f.deps);counts.push(f.calls.length-start);S.ack(a,r);held.push({record:r,artifact_id:a.artifact_id,artifact_digest:a.artifact_digest,body_sha256:S.hash(r)});}assert(counts.every(n=>n<=60));assert.deepEqual(held.map(x=>x.record.phase),['NO_WIRE','UNKNOWN','ACK']);fs.writeFileSync(path.join(root,'native-phase-counts-safe.json'),JSON.stringify({counts,max:60})+'\n');});
